import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"25、【无妄】 震下乾上","description":"横渠易说 - 25、【无妄】 震下乾上","frontmatter":{"title":"25、【无妄】 震下乾上","description":"横渠易说 - 25、【无妄】 震下乾上"},"headers":[],"relativePath":"zh/classics/hengqu/027.md","filePath":"zh/classics/hengqu/027.md"}'),t={name:"zh/classics/hengqu/027.md"};function l(n,a,s,c,d,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_25、【无妄】-震下乾上" tabindex="-1">25、【无妄】 震下乾上 <a class="header-anchor" href="#_25、【无妄】-震下乾上" aria-label="Permalink to “25、【无妄】 震下乾上”">​</a></h1><h3 id="彖曰-无妄-刚自外来而为主于内-动而健-刚中而应-大亨以正-天之命也。-其匪正有眚-不利有攸往-无妄之往何之矣-天命不祐-行矣哉" tabindex="-1">彖曰：无妄，刚自外来而为主于内，动而健，刚中而应，大亨以正，天之命也。“其匪正有眚，不利有攸往”，无妄之往何之矣!天命不祐，行矣哉! <a class="header-anchor" href="#彖曰-无妄-刚自外来而为主于内-动而健-刚中而应-大亨以正-天之命也。-其匪正有眚-不利有攸往-无妄之往何之矣-天命不祐-行矣哉" aria-label="Permalink to “彖曰：无妄，刚自外来而为主于内，动而健，刚中而应，大亨以正，天之命也。“其匪正有眚，不利有攸往”，无妄之往何之矣!天命不祐，行矣哉!”">​</a></h3><p>无妄四德，无妄而后具四德也。其曰“匪正有眚”，对无妄雷行天动也，天动不妄，故曰“无妄”。天动不妄则物亦无妄，乾道变化各正性命也。 象曰：天下雷行，物与无妄，先王以茂对时，育万物。 物因雷动，雷动不妄则物亦不妄，故曰“物与无妄”。育不以时，害莫甚焉。</p><h3 id="初九-无妄往吉。-象曰-无妄之往-得志也。" tabindex="-1">初九，无妄往吉。 象曰：无妄之往，得志也。 <a class="header-anchor" href="#初九-无妄往吉。-象曰-无妄之往-得志也。" aria-label="Permalink to “初九，无妄往吉。 象曰：无妄之往，得志也。”">​</a></h3><p>易所谓“得志”者，圣贤获其愿欲者也。得臣无家，尧之志也；贞吉升阶，舜之志也。</p><h3 id="六二-不耕获-不灾畲-则利有攸往。-象曰-不耕获-未富也。" tabindex="-1">六二，不耕获，不灾畲，则利有攸往。 象曰：“不耕获”，未富也。 <a class="header-anchor" href="#六二-不耕获-不灾畲-则利有攸往。-象曰-不耕获-未富也。" aria-label="Permalink to “六二，不耕获，不灾畲，则利有攸往。 象曰：“不耕获”，未富也。”">​</a></h3><p>柔之为道不利远者，能远利不为物首则可，乘刚处实则凶。</p><h3 id="六三-无妄之灾-或系之牛-行人之得-邑人之灾。-象曰-行人得牛-邑人灾也。" tabindex="-1">六三，无妄之灾，或系之牛，行人之得，邑人之灾。 象曰：行人得牛，邑人灾也。 <a class="header-anchor" href="#六三-无妄之灾-或系之牛-行人之得-邑人之灾。-象曰-行人得牛-邑人灾也。" aria-label="Permalink to “六三，无妄之灾，或系之牛，行人之得，邑人之灾。 象曰：行人得牛，邑人灾也。”">​</a></h3><p>妄灾之大，莫大于妄诛于人，以阴居阳，体躁而动，迁怒肆暴，灾之甚者。系牛为说，缘耕获 生词。</p><h3 id="九四-可贞-无咎。-象曰-可贞无咎-固有之也。" tabindex="-1">九四，可贞，无咎。 象曰：“可贞无咎”，固有之也。 <a class="header-anchor" href="#九四-可贞-无咎。-象曰-可贞无咎-固有之也。" aria-label="Permalink to “九四，可贞，无咎。 象曰：“可贞无咎”，固有之也。”">​</a></h3><h3 id="九五-无妄之疾-勿药有喜。-象曰-无妄之药-不可试也。" tabindex="-1">九五，无妄之疾，勿药有喜。 象曰：无妄之药，不可试也。 <a class="header-anchor" href="#九五-无妄之疾-勿药有喜。-象曰-无妄之药-不可试也。" aria-label="Permalink to “九五，无妄之疾，勿药有喜。 象曰：无妄之药，不可试也。”">​</a></h3><p>体健居尊，得行其志，故以无妄为疾。“无妄之疾”，疾无妄之谓也，欲妄动而不敢妄，是则以无妄为疾者也，如孟子言“有法家拂士”，是疾无妄者也。以无妄为病而医之，则妄之意遂矣，故曰“勿药有喜”，又曰“不可试也”，言不可用药治之。</p><h3 id="上九-无妄行-有眚-无攸利。-象曰-无妄之行-穷之灾也。" tabindex="-1">上九，无妄行，有眚，无攸利。 象曰：无妄之行，穷之灾也。 <a class="header-anchor" href="#上九-无妄行-有眚-无攸利。-象曰-无妄之行-穷之灾也。" aria-label="Permalink to “上九，无妄行，有眚，无攸利。 象曰：无妄之行，穷之灾也。”">​</a></h3><p>进而过中，是无妄而行也。</p>',14)])])}const f=e(t,[["render",l]]);export{_ as __pageData,f as default};
